from dataclasses import dataclass, field


@dataclass
class Result:
    failures: list = field(default_factory=list)
    warnings: list = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.failures


r = Result(warnings=["length bias"])
print(r.ok, bool(r.warnings))

